UPPER(coalesce(sellerCentralSales.ASIN, sellerCentralSessions.ASIN, amazonads.asin,nr.ASIN)) ) ) AS SC_Browser_Sessions, DIV0( IFNULL(sellerCentralSessions.Browser_Page_Views, 0), COUNT(*) OVER ( PARTITION BY coalesce(sellerCentralSales.DATE, sellerCentralSessions.DATE, amazonads.date,nr.date) , UPPER(coalesce(sellerCentralSales.ASIN, sellerCentralSessions.ASIN, amazonads.asin,nr.ASIN)) ) ) AS SC_Browser_Page_Views, DIV0( IFNULL(sellerCentralSessions.MobileApp_Page_Views, 0), COUNT(*) OVER ( PARTITION BY coalesce(sellerCentralSales.DATE, sellerCentralSessions.DATE, amazonads.date,nr.date) , UPPER(coalesce(sellerCentralSales.ASIN, sellerCentralSessions.ASIN, amazonads.asin,nr.ASIN)) ) ) AS SC_MobileApp_Page_Views, DIV0( IFNULL(sellerCentralSessions.MobileApp_Sessions, 0), COUNT(*) OVER ( PARTITION BY coalesce(sellerCentralSales.DATE, sellerCentralSessions.DATE, amazonads.date,nr.date) , UPPER(coalesce(sellerCentralSales.ASIN, sellerCentralSessions.ASIN, amazonads.asin,nr.ASIN)) ) ) AS SC_MobileApp_Sessions, DIV0( IFNULL(sellerCentralSessions.BuyBox_Percentage, 0), COUNT(*) OVER ( PARTITION BY coalesce(sellerCentralSales.DATE, sellerCentralSessions.DATE, amazonads.date,nr.date) , UPPER(coalesce(sellerCentralSales.ASIN, sellerCentralSessions.ASIN, amazonads.asin,nr.ASIN)) ) ) AS SC_BuyBox_Percentage, DIV0( IFNULL(Net_Revenue, 0), COUNT(*) OVER ( PARTITION BY coalesce(sellerCentralSales.DATE, sellerCentralSessions.DATE, amazonads.date,nr.date) , UPPER(coalesce(sellerCentralSales.ASIN, sellerCentralSessions.ASIN, amazonads.asin,nr.ASIN)) ) ) AS Net_Revenue, IFNULL(TOTAL_AD_SPEND_SESSION_SHARE, 0) AS TOTAL_AD_SPEND_SESSION_SHARE, IFNULL(TOTAL_AD_SALES_SESSION_SHARE, 0) AS TOTAL_AD_SALES_SESSION_SHARE, IFNULL(TOTAL_IMPRESSIONS_SESSION_SHARE, 0) AS TOTAL_IMPRESSIONS_SESSION_SHARE, IFNULL(TOTAL_CLICKS_SESSION_SHARE, 0) AS TOTAL_CLICKS_SESSION_SHARE, IFNULL(TOTAL_AD_CONVERSIONS_SESSION_SHARE, 0) AS TOTAL_AD_CONVERSIONS_SESSION_SHARE, IFNULL(DISPLAY_AD_SPEND, 0) AS DISPLAY_AD_